mod solution;

fn main() {
    let cases = [
    (r#"hit -> cog via [hot,dot,dog,lot,log,cog]"#, r#"5"#),
    (r#"hit -> hot via [hot]"#, r#"2"#),
    (r#"
hit -> hot via [hot]
"#, r#"2"#),
    (r#"  
hit -> cog via [hot,dot,dog,lot,log,cog]
  "#, r#"5"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS bidirectional-bfs");
}
